Use Node’s built-in `node:http` client and pass the Unix socket path as `socketPath`:

```js
import { request } from 'node:http';

const req = request(
  {
    socketPath: '/tmp/example-node.sock',
    path: '/',
  },
  (res) => {
    res.on('data', (chunk) => {
      process.stdout.write(String(chunk));
    });
  },
);

req.end();
```

For CommonJS:

```js
const http = require('node:http');

const req = http.request(
  {
    socketPath: '/var/run/docker.sock',
    path: '/containers/json',
  },
  (res) => {
    let body = '';

    res.on('data', (chunk) => {
      body += chunk;
    });

    res.on('end', () => {
      console.log(body);
    });
  },
);

req.end();
```

The Node.js API uses `socketPath` for Unix domain sockets. The search results do not show a built-in option for using a Unix domain socket specifically as an HTTP proxy.
